const input = $input.first().json;
const headers = input.headers ?? {};
const body = input.body ?? {};
const apiKey = headers['x-api-key'];
const pedidoId = headers['x-pedido-id'];

function failure(statusCode, error, message) {
  return [{ json: { valid: false, statusCode, error, message } }];
}

if (!apiKey) return failure(401, 'UNAUTHORIZED', 'x-api-key obrigatória');
if (apiKey !== 'turma2026') return failure(403, 'FORBIDDEN', 'x-api-key inválida');
if (!pedidoId) return failure(400, 'BAD_REQUEST', 'x-pedido-id obrigatório');
if (typeof body.nome !== 'string' || !body.nome.trim()) return failure(400, 'BAD_REQUEST', 'Campo nome é obrigatório');
if (typeof body.email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(body.email.trim())) return failure(400, 'BAD_REQUEST', 'Campo email é inválido');
if (typeof body.senha !== 'string' || !body.senha) return failure(400, 'BAD_REQUEST', 'Campo senha é obrigatório');
if (body.saldoInicial === undefined || !Number.isFinite(Number(body.saldoInicial)) || Number(body.saldoInicial) < 0) return failure(400, 'BAD_REQUEST', 'saldoInicial deve ser um número maior ou igual a zero');

return [{
  json: {
    valid: true,
    nome: body.nome.trim(),
    email: body.email.trim().toLowerCase(),
    senha: body.senha,
    saldo: Number(body.saldoInicial),
    pedidoId,
  },
}];

const input = $input.first().json;
const headers = input.headers ?? {};
const body = input.body ?? {};

const apiKey = headers['x-api-key'];
const pedidoId = headers['x-pedido-id'];

function failure(statusCode, error, message) {
  return [{ json: { valid: false, statusCode, error, message } }];
}

if (!apiKey) {
  return failure(401, 'UNAUTHORIZED', 'x-api-key obrigatória');
}

if (apiKey !== 'turma2026') {
  return failure(403, 'FORBIDDEN', 'x-api-key inválida');
}

if (!pedidoId) {
  return failure(400, 'BAD_REQUEST', 'x-pedido-id obrigatório');
}

const clienteId = Number(body.clienteId);
const valor = Number(body.valor);
const pagamentoId = String(body.pagamentoId ?? '').trim();
const tipo = String(body.tipo ?? 'DEBITO').trim().toUpperCase();

if (!Number.isInteger(clienteId) || clienteId <= 0) {
  return failure(400, 'BAD_REQUEST', 'clienteId inválido');
}

if (!Number.isFinite(valor) || valor <= 0) {
  return failure(400, 'BAD_REQUEST', 'valor deve ser maior que zero');
}

if (!pagamentoId) {
  return failure(400, 'BAD_REQUEST', 'pagamentoId obrigatório');
}
if (!['DEBITO', 'ESTORNO'].includes(tipo)) {
  return failure(400, 'BAD_REQUEST', 'tipo deve ser DEBITO ou ESTORNO');
}

return [{
  json: {
    valid: true,
    clienteId,
    valor,
    pagamentoId,
    tipo,
    pedidoId
  }
}];

const requisicao = $('Validar débito').item.json;
const raw = $json.clienteRaw;

function recusar(statusCode, error, message) {
  return [{
    json: {
      approved: false,
      statusCode,
      error,
      message
    }
  }];
}

if (!raw) {
  return recusar(
    404,
    'NOT_FOUND',
    'Cliente não encontrado'
  );
}

try {
  const cliente = typeof raw === 'string'
    ? JSON.parse(raw)
    : raw;

  if (!cliente?.id) {
    return recusar(
      404,
      'NOT_FOUND',
      'Cliente não encontrado'
    );
  }

  // Cria o histórico de operações caso ainda não exista
  if (!cliente.pagamentosProcessados) {
    cliente.pagamentosProcessados = {};
  }

  const pagamentoId = requisicao.pagamentoId;
  const valor = requisicao.valor;
  const tipo = requisicao.tipo ?? 'DEBITO';

  // Cada tipo de operação possui sua própria idempotência.
  // Exemplo:
  // PAG-001:DEBITO
  // PAG-001:ESTORNO
  const chaveOperacao = `${pagamentoId}:${tipo}`;

  // Verifica se a operação já foi processada
  let pagamentoAnterior =
    cliente.pagamentosProcessados[chaveOperacao];

  // Compatibilidade com registros antigos:
  // antes da alteração, os débitos eram salvos somente
  // usando o pagamentoId como chave.
  if (!pagamentoAnterior && tipo === 'DEBITO') {
    pagamentoAnterior =
      cliente.pagamentosProcessados[pagamentoId];
  }

  if (pagamentoAnterior) {

    const valorAnterior = Number(
      pagamentoAnterior.valor ??
      pagamentoAnterior.resposta?.valor ??
      pagamentoAnterior.resposta?.valorDebitado
    );

    const tipoAnterior =
      pagamentoAnterior.tipo ??
      pagamentoAnterior.resposta?.tipo ??
      'DEBITO';

    // Mesmo pagamentoId + mesmo tipo,
    // mas valor diferente = conflito
    if (
      valorAnterior !== Number(valor) ||
      tipoAnterior !== tipo
    ) {
      return recusar(
        400,
        'PAYMENT_ID_CONFLICT',
        'pagamentoId já foi usado com dados diferentes'
      );
    }

    // Mesma operação já processada:
    // não altera o saldo novamente.
    const respostaAnterior =
      pagamentoAnterior.resposta ?? {};

    return [{
      json: {
        approved: true,
        statusCode: 200,
        clienteId:
          respostaAnterior.clienteId ??
          pagamentoAnterior.clienteId ??
          cliente.id,

        pagamentoId:
          respostaAnterior.pagamentoId ??
          pagamentoId,

        tipo: tipo,

        valor: valorAnterior,

        saldoAtual:
          respostaAnterior.saldoAtual ??
          cliente.saldo,

        clienteAtualizado: JSON.stringify(cliente),

        idempotente: true
      }
    }];
  }

  const saldoAtual = Number(cliente.saldo);

  if (!Number.isFinite(saldoAtual)) {
    return recusar(
      500,
      'INTERNAL_ERROR',
      'Saldo do cliente inválido'
    );
  }

  let novoSaldo;
  let mensagemOperacao;

  // =========================
  // DÉBITO
  // =========================
  if (tipo === 'DEBITO') {

    // Débito só pode acontecer se houver saldo suficiente
    if (saldoAtual < valor) {
      return recusar(
        400,
        'INSUFFICIENT_FUNDS',
        'Saldo insuficiente para concluir o pagamento'
      );
    }

    novoSaldo =
      Math.round((saldoAtual - valor) * 100) / 100;

    mensagemOperacao =
      'Débito realizado com sucesso';

  // =========================
  // ESTORNO
  // =========================
  } else if (tipo === 'ESTORNO') {

    // Estorno devolve o valor para a carteira
    novoSaldo =
      Math.round((saldoAtual + valor) * 100) / 100;

    mensagemOperacao =
      'Estorno realizado com sucesso';

  } else {

    return recusar(
      400,
      'BAD_REQUEST',
      'Tipo de operação inválido'
    );
  }

  // Atualiza o saldo do cliente
  cliente.saldo = novoSaldo;
  cliente.atualizadoEm = new Date().toISOString();

  // Resultado da operação
  const resposta = {
    aprovado: true,
    clienteId: cliente.id,
    pagamentoId: pagamentoId,
    tipo: tipo,
    valor: valor,
    saldoAtual: novoSaldo,
    mensagem: mensagemOperacao
  };

  // Salva a operação usando pagamentoId + tipo.
  //
  // Exemplo:
  // PAG-001:DEBITO
  // PAG-001:ESTORNO
  //
  // Isso permite que o mesmo pagamento seja debitado
  // e posteriormente estornado sem conflito.
  cliente.pagamentosProcessados[chaveOperacao] = {
    clienteId: cliente.id,
    valor: valor,
    tipo: tipo,
    resposta: resposta
  };

  return [{
    json: {
      approved: true,
      statusCode: 200,
      clienteId: cliente.id,
      pagamentoId: pagamentoId,
      tipo: tipo,
      valor: valor,
      saldoAtual: novoSaldo,
      clienteAtualizado: JSON.stringify(cliente),
      idempotente: false
    }
  }];

} catch (error) {

  return recusar(
    500,
    'INTERNAL_ERROR',
    'Não foi possível processar o saldo do cliente'
  );
}

const headers = $json.headers || {};
const body = $json.body || {};

const apiKey = headers['x-api-key'] || headers['X-API-Key'];
const token = body.token;

function erro(statusCode, error, message) {
  return [{
    json: {
      statusCode,
      error,
      message
    }
  }];
}

// Valida x-api-key
if (apiKey !== 'turma2026') {
  return erro(
    403,
    'FORBIDDEN',
    'x-api-key inválida'
  );
}

// Valida token
if (!token || typeof token !== 'string' || !token.trim()) {
  return erro(
    401,
    'UNAUTHORIZED',
    'Token não informado'
  );
}

return [{
  json: {
    valid: true,
    token: token.trim()
  }
}];

const raw = $json.clienteRaw;

if (!raw) {
  return [{
    json: {
      statusCode: 401,
      error: 'UNAUTHORIZED',
      message: 'Token inválido'
    }
  }];
}

try {
  const cliente = typeof raw === 'string'
    ? JSON.parse(raw)
    : raw;

  if (!cliente?.id) {
    return [{
      json: {
        statusCode: 401,
        error: 'UNAUTHORIZED',
        message: 'Token inválido'
      }
    }];
  }

  return [{
    json: {
      statusCode: 200,
      id: cliente.id,
      nome: cliente.nome,
      email: cliente.email
    }
  }];

} catch (error) {
  return [{
    json: {
      statusCode: 500,
      error: 'INTERNAL_ERROR',
      message: 'Não foi possível validar o token'
    }
  }];
}

