const now = new Date().toISOString();

const response = $input.first().json;

const request = $('POST /v1/auth/validar').item.json;
const headers = request.headers ?? {};

const pedidoId =
  request.pedidoId ??
  headers['x-pedido-id'] ??
  headers['X-Pedido-Id'] ??
  null;

const eventId = `LOG-${$execution.id}-${Date.now()}`;

const success =
  Number(response.statusCode) === 200;

return [{
  json: {
    eventId,
    timestamp: now,
    service: '8',
    action: 'VALIDATE_TOKEN',
    status: success ? 'SUCCESS' : 'FAILED',
    level: success ? 'INFO' : 'WARN',
    message: success
      ? 'Token validado com sucesso'
      : (response.message || 'Token inválido'),
    pedidoId: pedidoId,
    metadata: success
      ? {
          clienteId: response.id
        }
      : {
          error: response.error
        }
  }
}];

const now = new Date().toISOString();

const response = $input.first().json;
const request = $('Validar débito').item.json;

const pedidoId = request.pedidoId ?? null;

