    eventId,
    timestamp: now,
    service: '8',
    action: 'GET_CLIENT',
    status: 'FAILED',
    level: 'WARN',
    message: response.message || 'Cliente não encontrado',
    pedidoId: pedidoId,
    metadata: {
      clienteId: request.clienteId,
      error: response.error
    }
  }
}];

const raw = $json.clienteRaw;
if (!raw) return [{ json: { found: false } }];

try {
  const cliente = typeof raw === 'string' ? JSON.parse(raw) : raw;
  if (!cliente?.id) return [{ json: { found: false } }];
  return [{ json: { found: true, cliente } }];
} catch (error) {
  return [{ json: { found: false } }];
