const input = $input.first().json;
const headers = input.headers ?? {};
const clienteId = input.params?.clienteId;
const apiKey = headers['x-api-key'];
const pedidoId = headers['x-pedido-id'];

function failure(statusCode, error, message) {
  return [{ json: { valid: false, statusCode, error, message } }];
}

if (!apiKey) return failure(401, 'UNAUTHORIZED', 'x-api-key obrigatória');
if (apiKey !== 'turma2026') return failure(403, 'FORBIDDEN', 'x-api-key inválida');
if (!pedidoId) return failure(400, 'BAD_REQUEST', 'x-pedido-id obrigatório');
if (typeof clienteId !== 'string' || !clienteId.trim()) return failure(400, 'BAD_REQUEST', 'clienteId é obrigatório');

return [{ json: { valid: true, clienteId: clienteId.trim(), pedidoId, resource: 'cliente' } }];

const request = $('POST /v1/clientes').item.json;

const headers = request.headers ?? {};

const pedidoId =
  request.pedidoId ??
